#include "snes/snes.h"

// Entry mode: A 8-bit (mf=1), X 16-bit (xf=0), DB=$9B (per module), DP=0
// Logic: Checks if player is on a map trigger. Handles frequency checks, 
// player control locking, and trigger execution (scripts, map transitions, or events).
void CheckTriggerSub_c(Snes *snes) {
    uint8_t *ram = snes->ram;

    ram[0xCD] = 0; // stz $cd
    if (ram[0xAB] != 0) { // lda $ab / bne @9bd7
        // Skip clearing $7b
    } else {
        ram[0x7B] = 0;
    }

    uint8_t trigger_rate_idx = ram[0xAC]; // lda $ac / tax
    uint8_t freq_mask = TriggerRateTbl[trigger_rate_idx]; // and TriggerRateTbl,x
    if ((ram[0x7B] & freq_mask) != 0) { // beq @9be4 (not taken)
        ram[0xD5] = 0; // disable player control
        return;
    }

    // @9be4: enable player control
    ram[0xD5] = 1;
    update_local_tiles_emu(snes);

    ram[0x1A02] = ram[0xA1] & 0x08; // lda $a1 / and #$08 / sta $1a02

    // Coordinate check: if x or y >= 0x20 or negative (BMI)
    int8_t x = (int8_t)ram[0x1706];
    int8_t y = (int8_t)ram[0x1707];
    if (x < 0 || x >= 0x20 || y < 0 || y >= 0x20) { // bmi/cmp sequence
        ram[0xD1]++; // inc $d1
        return;
    }

    // @9c07: Check for specific trigger conditions
    int8_t a2 = (int8_t)ram[0xA2];
    if (a2 >= 0 && (a2 & 0x10) == 0 && (ram[0xA1] & 0x08) == 0) {
        ram[0xD6] = 1;
        return;
    }

    // @9c1c:
    if (ram[0xD6] == 0) return;
    ram[0xD6] = 0; // stz $d6

    if ((ram[0xA1] & 0x08) != 0) {
        ram[0xB1] = 1;
        snes->cpu->a = 0x76; // lda #$76
        exec_event_emu(snes);
        ram[0xB1] = 0;
        return;
    }

    // @9c35:
    if (a2 >= 0) {
        ram[0xD1]++;
        return;
    }

    // @9c3c: Map Trigger Lookup
    // Calculate index: (ram[0x1702] << 1) + (ram[0x1701 != 0 ? 2 : 0])
    uint16_t idx_base = ram[0x1702] << 1; 
    if (ram[0x1701] != 0) {
        idx_base += 2; // inc $3e / inc $3e (where $3e is high byte of 16-bit shifted value)
    }

    // Load pointer from MapTriggersPtrs table
    uint16_t ptr = read16(&f_MapTriggersPtrs[idx_base], 0); // lda / lda+1
    
    // Iterate through MapTriggers1 list
    for (uint16_t x_ptr = ptr; ; x_ptr += 5) { // inx5 / jmp @9c60
        if (ram[x_ptr] == ram[0x1706] && ram[x_ptr + 1] == ram[0x1707]) {
            // Match found @9c7a
            uint8_t type = ram[x_ptr + 2];
            if (type != 0xFF) {
                snes->cpu->a = ram[x_ptr + 3];
                exec_trigger_script_emu(snes);
                return;
            }

            push_map_stack_emu(snes);
            if (type >= 0xFB) { // bcs @9cc2
                // Fade out and transition
                snes->cpu->x = x_ptr; // phx / plx for context
                fade_out_song_fast_emu(snes);
                wipe_out_emu(snes);
                
                ram[0x1700] = (uint8_t)(type - 0xFB); // sec / sbc #$fb
                ram[0x1706] = ram[x_ptr + 3];
                ram[0x1707] = ram[x_ptr + 4];
                ram[0xCD]++;
                write16(ram, 0x172C, 0);
                return;
            } else {
                // Map jump
                ram[0x1702] = type;
                uint8_t data = ram[x_ptr + 3];
                ram[0x1706] = data & 0x3F;
                ram[0x1705] = (data & 0xC0) >> 1; // lsr6
                ram[0x1707] = ram[x_ptr + 4];
                wipe_out_emu(snes);
                ram[0x1700] = 0x03;
                ram[0xCD]++;
                return;
            }
        }
    }
}


